window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0b3afe802ca17c5c"]={"versions": [{"id": "FIG-0b3afe802ca17c5c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm der AUTOSAR Classic Platform zur Veranschaulichung des Übertragungsmodus (Transmission Mode, TM) <code>MIXED</code> im Modul AUTOSAR COM (<code>AUTOSAR_SWS_COM</code>). Das Diagramm stellt das Sendezeitverhalten einer I-PDU bei Umschaltung des Transmission Mode Selectors (TMS) dar, kombiniert aus zyklischer Übertragung und ereignisgesteuerten Mehrfachübertragungen (<code>n = 3</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitachse: Horizontaler Zeitstrahl mit Unterbrechungssymbolen für periodische Intervalle.\n</li><li>Sendeereignisse (grüne Pfeile nach unten): Tatsächliche Sendezeitpunkte bzw. Übertragungsanforderungen an unterlagerte Schichten.\n</li><li>Unterdrücktes Sendeereignis (gestrichelter blauer Pfeil nach oben): Durch Mindestabstands- bzw. Zyklusbedingungen verschobenes oder maskiertes zyklisches Senden.\n</li><li>Signalaktualisierungen (rote Blitze): Schreib- bzw. Sendeaufrufe aus der Applikation (<code>Com_SendSignal</code>) mit neuen Werten (<code>v = b</code> bzw. <code>v = a</code>), die den TMS beeinflussen oder ein direktes Senden anstoßen.\n</li><li>Konfigurationsparameter und Zeitdauern:\n<ul class=\"fig-list\"><li><code>t_c1</code>: Zykluszeit im Übertragungsmodus A (<code>v = a</code>).\n</li><li><code>t_c2</code>: Zykluszeit im Übertragungsmodus B (<code>v = b</code>).\n</li><li><code>y*t_c1</code>, <code>z*t_c2</code>: Vielfache der jeweiligen Zykluszeit.\n</li><li><code>dt</code>: Zeitdifferenz/Offset zwischen letztem periodischen Sendeereignis und Applikationsereignis.\n</li><li><code>t_r,min</code>: Mindestverzögerung (Minimum Delay Time, MDT) vor dem Auslösen der ersten Ereignisübertragung.\n</li><li><code>t_d</code>: Wiederholungsabstand (Repetition Period) für die <code>n = 3</code> Übertragungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialer Zustand (<code>v = a</code>): Die I-PDU wird rein periodisch mit der Zykluszeit <code>t_c1</code> gesendet. Nach einem Vielfachen <code>y*t_c1</code> verstreicht eine Zeitspanne <code>dt</code>.\n</li><li>TMS-Umschaltung zu Modus B (<code>v = b</code>): Eine Signalaktualisierung schaltet den TMS um. Nach Ablauf der Mindestverzögerung <code>t_r,min</code> startet das Senden im Modus B mit der neuen Zykluszeit <code>t_c2</code> (gefolgt von <code>z*t_c2</code>).\n</li><li>Rückschaltung zu Modus A (<code>v = a</code>) mit Mischverhalten: Eine erneute Signalaktualisierung löst eine Burst-Sequenz mit <code>n = 3</code> Übertragungen aus (erste Übertragung nach Ablauf von <code>t_r,min</code>, gefolgt von zwei Wiederholungen im Abstand <code>t_d</code>).\n</li><li>Anschließender Zyklusbetrieb: Nach der Burst-Übertragung wird der periodische Takt mit Zykluszeit <code>t_c1</code> fortgesetzt.\n</li><li>Erneute Signalaktualisierung im Modus A (<code>v = a</code>): Löst wiederum <code>n = 3</code> Übertragungen im Abstand <code>t_d</code> aus. Ein regulärer zyklischer Sendezeitpunkt fiele in dieses Intervall und wird markiert/überlagert, woraufhin die Zykluszeit <code>t_c1</code> ab dem Referenzzeitpunkt neu berechnet wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm konkretisiert die Anforderungen bezüglich der Kombination aus periodischer Übertragung (<code>ComTxModeTimePeriod</code>) und ereignisgesteuerten Mehrfachübertragungen (<code>ComTxModeNumberOfRepetitions = 3</code>, <code>ComTxModeRepetitionPeriod = t_d</code>).\n</li><li>Es visualisiert das Zusammenspiel zwischen Mindestabstandszeit (<code>ComMinimumDelayTime = t_r,min</code>) und TMS-Moduswechsel (<code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li><li>Relevant für COM-Implementierer zur korrekten Synchronisation bzw. Rücksetzung des periodischen Sende-Timers nach Übertragungsbursts und Moduswechseln.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0be675c685bd002c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm der AUTOSAR Classic Platform zur Veranschaulichung des Übertragungsmodus (Transmission Mode, TM) <code>MIXED</code> im Modul AUTOSAR COM (<code>AUTOSAR_SWS_COM</code>). Das Diagramm stellt das Sendezeitverhalten einer I-PDU bei Umschaltung des Transmission Mode Selectors (TMS) dar, kombiniert aus zyklischer Übertragung und ereignisgesteuerten Mehrfachübertragungen (<code>n = 3</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitachse: Horizontaler Zeitstrahl mit Achsenbezeichnung <code>t</code> und Unterbrechungssymbolen für periodische Intervalle.\n</li><li>Sendeereignisse (grüne Pfeile nach unten): Tatsächliche Sendezeitpunkte bzw. Übertragungsanforderungen an unterlagerte Schichten.\n</li><li>Signalaktualisierungen (rote offene Dreiecksmarkierungen): Schreib- bzw. Sendeaufrufe aus der Applikation mit neuen Werten (<code>v = b</code> bzw. <code>v = a</code>), die den TMS beeinflussen.\n</li><li>Konfigurationsparameter und Zeitdauern:\n<ul class=\"fig-list\"><li><code>t_c1</code>: Zykluszeit im Übertragungsmodus A (<code>v = a</code>).\n</li><li><code>t_c2</code>: Zykluszeit im Übertragungsmodus B (<code>v = b</code>).\n</li><li><code>y*t_c1</code>, <code>z*t_c2</code>: Vielfache der jeweiligen Zykluszeit (gestrichelt gekennzeichnet).\n</li><li><code>d</code>: Zeitdifferenz zwischen letztem periodischen Sendeereignis und Applikationsereignis bzw. nachfolgenden Übertragungen.\n</li><li><code>t_r,min</code>: Mindestverzögerung (Minimum Delay Time) vor der Ausführung der ereignisgesteuerten Übertragung.\n</li><li><code>t_d</code>: Wiederholungsabstand für die <code>n = 3</code> Übertragungen im Burst.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initialer Zustand (<code>v = a</code>): Die I-PDU wird zyklisch mit Zykluszeit <code>t_c1</code> übertragen; nach dem Intervall <code>y*t_c1</code> vergeht eine Zeitspanne <code>d</code>.\n</li><li>TMS-Umschaltung zu Modus B (<code>v = b</code>): Nach Ablauf der Mindestverzögerung <code>t_r,min</code> beginnt das zyklische Senden im Modus B mit der Periode <code>t_c2</code> (über <code>z*t_c2</code>).\n</li><li>Rückschaltung zu Modus A (<code>v = a</code>): Nach Ablauf von <code>d</code> und <code>t_r,min</code> wird eine Sequenz von <code>n = 3</code> Übertragungen mit dem Abstand <code>t_d</code> gesendet.\n</li><li>Fortführung des Betriebs: Zeitgleich mit der ersten Übertragung der Sequenz startet das periodische Intervall <code>t_c1</code>. Nach Abschluss der Wiederholungen setzt sich das rein zyklische Senden mit festen Perioden <code>t_c1</code> ohne weitere Burst-Übertragungen fort.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm konkretisiert die Anforderungen bezüglich der Kombination aus periodischer Übertragung (<code>ComTxModeTimePeriod</code>) und ereignisgesteuerten Mehrfachübertragungen (<code>ComTxModeNumberOfRepetitions = 3</code>, <code>ComTxModeRepetitionPeriod = t_d</code>).\n</li><li>Es visualisiert das Zusammenspiel zwischen Mindestabstandszeit (<code>ComMinimumDelayTime = t_r,min</code>) und TMS-Moduswechsel (<code>ComTxModeTrue</code> / <code>ComTxModeFalse</code>).\n</li><li>Relevant für COM-Implementierer zur korrekten Synchronisation bzw. Rücksetzung des periodischen Sende-Timers nach Übertragungsbursts und Moduswechseln.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0b3afe802ca17c5c", "to": "FIG-0be675c685bd002c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zeitstrahl: Achsenbeschriftung <code>t</code> am rechten Pfeilende ergänzt.\n</li><li>Ereignissymbole: Die roten Blitze für Signalaktualisierungen (<code>v = b</code>, <code>v = a</code>) wurden durch rote offene Dreiecksmarkierungen ersetzt.\n</li><li>Zeitintervalle / Multiplikatoren: Die Pfeile für die ganzzahligen Periodensprünge <code>y*t_c1</code> und <code>z*t_c2</code> wurden von durchgezogenen Doppelpfeilen auf gestrichelte Doppelpfeile umgestellt.\n</li><li>Zeitmarken-Beschriftung: Der Offset-Parameter <code>dt</code> wurde zu <code>d</code> umbenannt und als Klammerbereich unterhalb der Zeitachse dargestellt.\n</li><li>Normatives Verhalten am rechten Diagrammende: Das dritte Aktualisierungsereignis (<code>v = a</code>) inklusive der N-fachen Wiederholungen (<code>t_d</code>, <code>t_d</code>), der gestrichelten blauen Sendeunterdrückung/Offset-Marke sowie der übergeordneten Periodendauer <code>t_c1</code> entfällt vollständig; stattdessen folgen nach dem Wiedereinschwingen auf Modus A reguläre periodische Sendezeitpunkte im festen Abstand <code>t_c1</code>.\n</li></ul>"}]};
